from ta_emss.utilities.trs.commands.emssim import EmssimCommand


class Parse_pm_file(EmssimCommand):
    def __init__(self, method="parse_pm_file", timeout=300, rpc_connection_name='localRPC'):
        super(Parse_pm_file, self).__init__(method, timeout, rpc_connection_name)
        self.params = None

    def on_new_data(self, **data):
        data = super(Parse_pm_file, self).on_new_data(**data)
        if "measurement" in data:
            if "measurement_table" not in self._ret.keys():
                self._ret["measurement_table"] = []
            self._ret["measurement_table"].append(data)
        elif ("status" in data):
            self._ret["status"] = data["status"]
